615: bool EnableExternalAccessSetting::OnGlobalSet(DatabaseInstance *db, DBConfig &config, const Value &input) {
616: 	if (!db) {
617: 		return true;
618: 	}
619: 	if (input.GetValue<bool>()) {
620: 		throw InvalidInputException("Cannot change enable_external_access setting while database is running");
621: 	}
622: 	if (db && config.options.enable_external_access) {
623: 		// we are turning off external access - add any already attached databases to the list of accepted paths
624: 		auto &db_manager = DatabaseManager::Get(*db);
625: 		auto attached_paths = db_manager.GetAttachedDatabasePaths();
626: 		for (auto &path : attached_paths) {
627: 			config.AddAllowedPath(path);
628: 			config.AddAllowedPath(path + ".wal");
629: 		}
630: 	}
631: 	if (config.options.use_temporary_directory && !config.options.temporary_directory.empty()) {
632: 		// if temp directory is enabled we can also write there
633: 		config.AddAllowedDirectory(config.options.temporary_directory);
634: 	}
635: 	return true;
636: }
